sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {

        var updateBulkRec = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
        updateBulkRec.get(current.bulk_id.sys_id);
        gs.info('Bulk Record before update' + current.number + updateBulkRec.bulk_task_type + updateBulkRec.number);

        if (current.trade_task_type == 'Maker') {
            updateBulkRec.bulk_task_type = 'Maker';
        } else if (current.trade_task_type == 'Checker') {
            updateBulkRec.bulk_task_type = 'Checker';
        } else if (current.trade_task_type == 'GHSS Handler - Amend') {
            updateBulkRec.bulk_task_type = 'GHSS Handler';
        }
        updateBulkRec.update();
        gs.info('Bulk Record after update' + current.number + updateBulkRec.bulk_task_type + updateBulkRec.number);

    } catch (ex) {
        gs.info('Error reported  from Business Rule Amend - Update bulk Task Type ' + ex);
    }

})(current, previous);
